import json,glob
SOFT,HARD=4,6
def simulate(t):
    m=json.load(open(t+".messages.json"))
    msgs=m if isinstance(m,list) else m.get("messages",[])
    seq=[]; lastcmd=None
    for x in msgs:
        if not isinstance(x,dict): continue
        if x.get("role")=="assistant" and x.get("tool_calls"):
            for tc in x["tool_calls"]:
                a=tc.get("function",{}).get("arguments","")
                try: a=json.loads(a)
                except: pass
                lastcmd=(a.get("command","") if isinstance(a,dict) else str(a)).strip()
        elif x.get("role")=="tool":
            c=x.get("content"); c=c if isinstance(c,str) else json.dumps(c)
            seq.append((lastcmd,c.strip()))
    # simulate breaker
    last=(None,None); streak=0; nudges=0; blocks=0; nudged_cmd=None
    for cmd,res in seq:
        # before_tool block check happens BEFORE execution: if cmd==last_cmd and streak>=HARD -> block, don't execute
        if cmd==last[0] and streak>=HARD:
            blocks+=1
            continue  # blocked, not executed, streak unchanged
        # execute
        if (cmd,res)==last and cmd:
            streak+=1
        else:
            streak=1; nudged_cmd=None
        last=(cmd,res)
        if SOFT<=streak<HARD and nudged_cmd!=cmd:
            nudged_cmd=cmd; nudges+=1
    return nudges,blocks
res=[]
for f in sorted(glob.glob("task_*.result.json")):
    d=json.load(open(f)); t=d["task_id"]
    n,b=simulate(t)
    if n or b:
        res.append((d["reward"],t,d["agent"]["exit_reason"],n,b))
print("reward task exit nudges blocks")
for r in sorted(res):
    print(r)
